const NULL = '__null__';

export async function getOrLoad(client, key, load, { ttl = 300, nullTtl = 30 } = {}) {
  const hit = await client.get(key).catch(() => null); // fail open if Redis is unhealthy
  if (hit !== null) return hit === NULL ? null : JSON.parse(hit);
  const value = await load();
  const t = value === null ? nullTtl : Math.round(ttl * (0.9 + Math.random() * 0.2));
  client.set(key, value === null ? NULL : JSON.stringify(value), { EX: t }).catch(() => {});
  return value;
}

const inflight = new Map();

export function loadOnce(client, key, load, ttl = 300) {
  if (inflight.has(key)) return inflight.get(key);
  const p = (async () => {
    const cached = await client.get(key);
    if (cached !== null) return JSON.parse(cached);
    const got = await client.set('lock:' + key, '1', { NX: true, PX: 5000 });
    if (!got) { // another instance is rebuilding: wait briefly, then re-read
      await new Promise((r) => setTimeout(r, 100));
      const again = await client.get(key);
      if (again !== null) return JSON.parse(again);
    }
    const value = await load();
    await client.set(key, JSON.stringify(value), { EX: ttl });
    return value;
  })().finally(() => inflight.delete(key));
  inflight.set(key, p);
  return p;
}

export async function swr(client, key, load, { soft = 60, hard = 600 } = {}) {
  const raw = await client.get(key);
  if (raw !== null) {
    const { v, exp } = JSON.parse(raw);
    if (Date.now() >= exp) refresh().catch(() => {}); // stale: serve now, refresh in background
    return v;
  }
  return refresh();

  async function refresh() { // combine with single-flight so only one refresh runs
    const v = await load();
    await client.set(key, JSON.stringify({ v, exp: Date.now() + soft * 1000 }), { EX: hard });
    return v;
  }
}

const SCRIPT = [
  "local n = redis.call('INCR', KEYS[1])",
  "if n == 1 then redis.call('PEXPIRE', KEYS[1], ARGV[1]) end",
  'return n'
].join('\n');

export async function allow(client, id, limit = 100, windowMs = 60000) {
  const n = await client.eval(SCRIPT, { keys: ['rl:' + id], arguments: [String(windowMs)] });
  return { allowed: n <= limit, remaining: Math.max(0, limit - n) };
}

import { randomUUID } from 'node:crypto';

const UNLOCK = [
  "if redis.call('GET', KEYS[1]) == ARGV[1] then",
  "  return redis.call('DEL', KEYS[1])",
  'end',
  'return 0'
].join('\n');

export async function withLock(client, name, ttlMs, fn) {
  const token = randomUUID();
  const ok = await client.set('lock:' + name, token, { NX: true, PX: ttlMs });
  if (!ok) return { acquired: false };
  try {
    return { acquired: true, result: await fn() };
  } finally {
    await client.eval(UNLOCK, { keys: ['lock:' + name], arguments: [token] });
  }
}
// If fn can outlive ttlMs, add fencing tokens or a database constraint for correctness.

export async function versionedKey(client, group, id) {
  const v = (await client.get('ver:' + group)) ?? '1';
  return group + ':v' + v + ':' + id;
}

// Invalidate every key in the group at once; old keys age out through TTL or eviction.
export const invalidateGroup = (client, group) => client.incr('ver:' + group);

const l1 = new Map(); // bound the size, or use an LRU, in real code
const sub = client.duplicate();      // subscriber mode needs its own connection
await sub.connect();
await sub.subscribe('invalidate', (key) => l1.delete(key));

export async function get(key) {
  const hit = l1.get(key);
  if (hit && hit.exp > Date.now()) return hit.v;
  const raw = await client.get(key);
  if (raw === null) return null;
  const v = JSON.parse(raw);
  l1.set(key, { v, exp: Date.now() + 5000 }); // short L1 TTL bounds staleness
  return v;
}

export async function invalidate(key) {
  await client.del(key);
  await client.publish('invalidate', key);
}

export async function deleteByPattern(client, pattern) {
  let cursor = '0';
  let total = 0;
  do {
    const res = await client.scan(cursor, { MATCH: pattern, COUNT: 500 });
    cursor = String(res.cursor);
    if (res.keys.length) total += await client.unlink(res.keys);
  } while (cursor !== '0');
  return total;
}
// Prefer versioned keys over pattern deletes. SCAN can return a key more than once.

export const addScore = (client, board, player, points) =>
  client.zIncrBy('lb:' + board, points, player);

export const top = (client, board, n = 10) =>
  client.zRangeWithScores('lb:' + board, 0, n - 1, { REV: true });

export async function rank(client, board, player) {
  const r = await client.zRevRank('lb:' + board, player); // zero-based, null if absent
  return r === null ? null : r + 1;
}
